package org.audiveris.omr.score;
import java.nio.file.*;import java.util.*;import java.awt.*;import java.awt.geom.Point2D;import java.awt.image.BufferedImage;import javax.imageio.ImageIO;import java.security.*;
import org.audiveris.omr.sheet.*;import org.audiveris.omr.sig.inter.*;import org.audiveris.omr.glyph.*;import org.audiveris.omr.classifier.*;import org.audiveris.omr.run.*;import org.audiveris.omr.math.Rational;import ij.process.ByteProcessor;
public class SourceBootstrap364 {
 static void req(boolean b,String s){if(!b)throw new IllegalArgumentException(s);}
 static String sha(Path p)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}
 static ByteProcessor raster(BufferedImage image,Rectangle b){var crop=new BufferedImage(b.width,b.height,BufferedImage.TYPE_BYTE_GRAY);var g=crop.createGraphics();g.drawImage(image.getSubimage(b.x,b.y,b.width,b.height),0,0,null);g.dispose();var bp=new ByteProcessor(crop);bp.threshold(159);return bp;}
 public static void main(String[] a){try{run(a);System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
 static void run(String[] a)throws Exception{
  ((ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(org.slf4j.Logger.ROOT_LOGGER_NAME)).setLevel(ch.qos.logback.classic.Level.WARN);
  Path input=Path.of(a[0]),source=Path.of(a[1]),out=Path.of(a[3]);String before=sha(input);Files.createDirectories(out);var book=Book.loadBook(input);req(book!=null,"load failed");SourceStructure335.source=source;
  var groups=new LinkedHashMap<String,java.util.List<String[]>>();for(String line:Files.readAllLines(Path.of(a[2]))){if(line.isBlank())continue;var f=line.split("\t");req(f.length==12,"plan fields");groups.computeIfAbsent(String.join("/",Arrays.copyOf(f,4)),k->new ArrayList<>()).add(f);}int created=0;
  for(var rows:groups.values()){
   req(rows.size()>=2,"bootstrap needs multiple aligned source heads");var f=rows.getFirst();int unit=Integer.parseInt(f[0]);var png=source.resolve(String.format("unit-%03d.png",unit));req(sha(png).equals(f[11]),"source pixels changed");var image=ImageIO.read(png.toFile());var sheet=book.getStub(unit).getSheet();var sys=sheet.getSystems().stream().filter(v->v.getId()==Integer.parseInt(f[1])).findFirst().orElseThrow();var staff=sys.getStaves().stream().filter(v->v.getId()==Integer.parseInt(f[3])).findFirst().orElseThrow();var stack=sys.getStacks().stream().filter(v->v.getIdValue()==Integer.parseInt(f[2])).findFirst().orElseThrow();var measure=stack.getMeasureAt(staff.getPart());var sig=sys.getSig();
   req(staff.getPart().getStaves().size()==2,"not piano grandstaff");req(Rational.ONE.equals(stack.getExpectedDuration()),"not independently validated 4/4");req(measure.getHeadChords().stream().noneMatch(c->c.getStaff()==staff)&&measure.getRestChords().stream().noneMatch(c->c.getStaff()==staff),"bootstrap requires empty physical staff lane");
   double interline=staff.getSpecificInterline();var heads=new ArrayList<HeadInter>();double grade=1,x0=-1;var positions=new HashSet<Integer>();
   for(var row:rows){req(row[11].equals(f[11]),"mixed provenance");var b=new Rectangle(Integer.parseInt(row[4]),Integer.parseInt(row[5]),Integer.parseInt(row[6]),Integer.parseInt(row[7]));req(b.x>=stack.getLeft()&&b.getMaxX()<=stack.getRight(),"head outside bar");double pitch=staff.pitchPositionOf(new Point2D.Double(b.getCenterX(),b.getCenterY()));int pp=Integer.parseInt(row[8]);req(Math.abs(pp)<=4&&Math.abs(pitch-pp)<=.2,"in-staff source pitch grid");req(positions.add(pp),"duplicate source pitch");if(x0<0)x0=b.getCenterX();else req(Math.abs(b.getCenterX()-x0)<.25*interline,"non-aligned head group");req(measure.getClefBefore(b.getLocation(),staff)!=null,"missing source clef");
    req(sig.vertexSet().stream().noneMatch(n->n instanceof HeadInter&&n.getBounds().intersects(b)),"existing head collision");req(sig.vertexSet().stream().noneMatch(n->n instanceof WordInter&&n.getBounds().intersects(b)),"music word collision");var stemZone=new Rectangle(b);stemZone.grow((int)Math.ceil(.3*interline),0);req(sig.vertexSet().stream().noneMatch(n->n instanceof StemInter&&n.getBounds().intersects(stemZone)),"stem would change note value");
    var rt=new RunTableFactory(Orientation.VERTICAL).createTable(raster(image,b));var evals=ShapeClassifier.getInstance().getNaturalEvaluations(new Glyph(0,0,rt),(int)Math.rint(interline));Arrays.sort(evals,Evaluation.byReverseGrade);var top=evals[0];double second=evals[1].grade;req(top.shape==org.audiveris.omr.glyph.Shape.METRO_WHOLE&&top.grade>=.5&&top.grade-second>=.35,"native whole classifier guard");req(Math.abs(top.grade-Double.parseDouble(row[9]))<1e-9&&Math.abs(second-Double.parseDouble(row[10]))<1e-9,"classification receipt mismatch");
    var head=new HeadInter(b,org.audiveris.omr.glyph.Shape.WHOLE_NOTE,top.grade,staff,(double)pp);head.setGlyph(sheet.getGlyphIndex().registerOriginal(new Glyph(b.x,b.y,rt)));heads.add(head);grade=Math.min(grade,top.grade);
   }
   var chord=new HeadChordInter(grade);chord.setStaff(staff);chord.setMeasure(measure);sig.addVertex(chord);measure.addInter(chord);for(var h:heads){sig.addVertex(h);chord.addMember(h);created++;}
   new org.audiveris.omr.sheet.rhythm.PageRhythm(sys.getPage()).reprocessStack(stack);req(chord.getVoice()!=null&&Rational.ZERO.equals(chord.getTimeOffset())&&Rational.ONE.equals(chord.getDuration()),"native whole chord clock");System.out.println("BOOTSTRAP_SOURCE_WHOLES "+String.join("/",Arrays.copyOf(f,4))+" heads="+heads.size());
  }
  for(var stub:book.getStubs())stub.setModified(true);book.setModified(true);book.store(out.resolve("refined.omr"),false);book=Book.loadBook(out.resolve("refined.omr"));req(book!=null,"reload failed");book.setExportPathSansExt(out.resolve("result"));req(book.export(book.getValidStubs(),book.getScores()),"export failed");SourceStructure335.writeLedgers(out);req(sha(input).equals(before),"input book changed");System.out.println("BOOTSTRAP364_EXPORTED heads="+created);
 }
}
